H('11. Acceptance Criteria Status'); T([['Target','Current evidence','Status'],['Forecast MAPE ≤12%','Prophet MAPE 27.50% on non-zero days','Not met'],['Churn ROC-AUC ≥0.88','Optuna temporal ROC-AUC 0.7695','Not met'],['Precision@top 20% ≥0.75','Optuna temporal 0.7555; baseline temporal 0.7381','Validation-dependent'],['Inventory reduction 25–40%','No measured intervention outcomes','Not measured'],['Stockout reduction 30–50%','No stock/stockout labels','Not measured'],['Revenue improvement 15–25%','No controlled impact evaluation','Not measured'],['Configured data checks','36 pass; 0 fail','Completed'],['Public HTTPS demo','Deployment not verified','Outstanding'],['Docker/Kubernetes/CI/CD/Airflow','Not fully completed and validated','Outstanding']],[49*mm,78*mm,41*mm]); P('Business impact is marked not measured, rather than a failed experiment: required operational labels and controlled intervention results are unavailable.','Callout'); pg()
