H('12. Architecture and Methods'); T([['Layer','Implementation'],['Input','Excel workbook with two historical retail sheets.'],['Preparation','Python/Pandas cleaning, feature engineering and quality validation.'],['Analytics','EDA, RFM transformations, K-Means and DBSCAN.'],['Forecasting','Daily series, Prophet, PyTorch Lightning LSTM, holdout comparison and ensemble.'],['Churn','XGBoost, temporal snapshots, Optuna, SHAP and feature importance.'],['Inventory','Historical product demand rates, review categories and confidence audit.'],['Monitoring','Evidently reports and local experiment/artifact records.'],['Presentation','Streamlit dashboard with analytical views and downloads.']],[39*mm,129*mm]); H2('Methodological notes')
